using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using PixelTart.SelectionApi.Contracts;
namespace PixelTart.SelectionApi.Server;
public sealed class SelectionApiException(int statusCode,string code,string message):Exception(message){public int StatusCode{get;}=statusCode;public string Code{get;}=code;}
public sealed record StoredAsset(Guid Id,string Name,string UploadSha,long Bytes,string Thumb,string Preview,string Proxy,bool Selected=false,bool Favorite=false);
public sealed record StoredProject(Guid Id,string PublicId,string Name,string Client,int Target,DateTimeOffset? Deadline,string OwnerHash,string CreateFingerprint,UpsertSelectionRuleRequest Rule)
{
 public UpsertSelectionRuleRequest Rule{get;set;}=Rule; public int Target{get;set;}=Target;
 public string Status{get;set;}="Draft";public int Version{get;set;}=1;public long Revision{get;set;}=0;public bool Locked{get;set;}=false;public string? ClientHash{get;set;}public DateTimeOffset? Expires{get;set;}public DateTimeOffset? ConfirmedAt{get;set;}public long? ConfirmedRevision{get;set;}
 public Dictionary<Guid,StoredAsset> Assets{get;set;}=[];public HashSet<string> Operations{get;set;}=[];
}
public sealed class LocalDevSelectionRepository:IDisposable
{
 private readonly SemaphoreSlim gate=new(1,1);private readonly string file;private readonly byte[] secret;private readonly FileStream processLock;
 internal static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){WriteIndented=true};
 public LocalDevSelectionRepository(string root){Directory.CreateDirectory(root);file=Path.Combine(root,"selection-v1.json");processLock=new(file+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);var key=Path.Combine(root,"server-secret.bin");if(!File.Exists(key)){using var f=new FileStream(key,FileMode.CreateNew);f.Write(RandomNumberGenerator.GetBytes(32));}secret=File.ReadAllBytes(key);if(secret.Length!=32)throw new InvalidDataException("Invalid local server secret");}
 static SelectionApiException Fail(int status,string code,string message)=>new(status,code,message);
 static string Hash(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));
 static bool Token(string? supplied,string? stored){if(string.IsNullOrWhiteSpace(supplied)||string.IsNullOrWhiteSpace(stored))return false;return CryptographicOperations.FixedTimeEquals(SHA256.HashData(Encoding.UTF8.GetBytes(supplied)),Convert.FromHexString(stored));}
 string Owner(Guid id)=>Convert.ToHexString(HMACSHA256.HashData(secret,Encoding.UTF8.GetBytes("owner/v1/"+id.ToString("N"))));
 async Task<T> State<T>(Func<Dictionary<Guid,StoredProject>,Task<T>> action,bool write=false,CancellationToken ct=default){await gate.WaitAsync(ct);try{var db=File.Exists(file)?JsonSerializer.Deserialize<Dictionary<Guid,StoredProject>>(await File.ReadAllTextAsync(file,ct),Json)??throw new InvalidDataException("Invalid server state"):[];var value=await action(db);if(write){var staging=file+"."+Guid.NewGuid().ToString("N")+".tmp";try{await File.WriteAllTextAsync(staging,JsonSerializer.Serialize(db,Json),ct);File.Move(staging,file,true);}finally{if(File.Exists(staging))File.Delete(staging);}}return value;}finally{gate.Release();}}
 static StoredProject Find(Dictionary<Guid,StoredProject> db,Guid id)=>db.GetValueOrDefault(id)??throw Fail(404,"ProjectNotFound","Project not found.");
 static StoredProject Auth(Dictionary<Guid,StoredProject>db,Guid id,string token,bool client=false){var p=Find(db,id);if(!Token(token,client?p.ClientHash:p.OwnerHash))throw Fail(401,"InvalidToken","Album access denied.");if(client){if(p.Status is not("Published" or "ClientConfirmed"))throw Fail(404,"ProjectNotPublished","Link is unavailable.");if(p.Expires is null||p.Expires<=DateTimeOffset.UtcNow)throw Fail(410,"LinkExpired","Link has expired.");}return p;}
 public Task<LocalDevCreateProjectResponse> Create(CreateSelectionProjectRequest req,string key,CancellationToken ct)=>State(db=>{if(req.ClientProjectId is not Guid id||id==Guid.Empty||key!="project:"+id.ToString("N")||string.IsNullOrWhiteSpace(req.Name)||string.IsNullOrWhiteSpace(req.ClientDisplayName)||req.TargetCount<1)throw Fail(400,"InvalidProject","Stable project id/name/client/count required.");var fingerprint=Hash(JsonSerializer.Serialize(req,Json));if(db.TryGetValue(id,out var existing)){if(existing.CreateFingerprint!=fingerprint)throw Fail(409,"IdempotencyConflict","Project retry payload changed.");return Task.FromResult(new LocalDevCreateProjectResponse(Project(existing),Owner(id)));}var p=new StoredProject(id,Convert.ToHexString(RandomNumberGenerator.GetBytes(18)).ToLowerInvariant(),req.Name.Trim(),req.ClientDisplayName.Trim(),req.TargetCount,req.DeadlineUtc,Hash(Owner(id)),fingerprint,new(req.TargetCount,0,req.TargetCount,true,0,true,true,false,true,false,req.DeadlineUtc,false,true));db.Add(id,p);return Task.FromResult(new LocalDevCreateProjectResponse(Project(p),Owner(id)));},true,ct);
 public Task<SelectionProjectResponse> Get(Guid id,string token,CancellationToken ct)=>State(db=>Task.FromResult(Project(Auth(db,id,token))),ct:ct);
 public Task<LocalDevAssetUploadResponse> Upload(Guid id,Guid asset,string token,string name,string sha,LocalDevJpegVariants variants,ISelectionObjectStorage storage,CancellationToken ct)=>State(async db=>{var p=Auth(db,id,token);if(asset==Guid.Empty||name!=Path.GetFileName(name)||string.IsNullOrWhiteSpace(name))throw Fail(400,"InvalidAsset","Stable asset id and file name required.");if(p.Assets.TryGetValue(asset,out var prior)){if(prior.UploadSha!=sha||prior.Name!=name)throw Fail(409,"IdempotencyConflict","Upload retry content changed.");return Uploaded(p,prior);}if(p.Locked||p.Status=="Published")throw Fail(409,"ProjectPublished","Unpublish before changing uploaded assets.");var thumb=await storage.PutImageAsync(id,asset,SelectionObjectVariant.Thumb,"proxy.jpg",new MemoryStream(variants.Thumb,false),ct);var preview=await storage.PutImageAsync(id,asset,SelectionObjectVariant.Preview,"proxy.jpg",new MemoryStream(variants.Preview,false),ct);var proxy=await storage.PutImageAsync(id,asset,SelectionObjectVariant.Proxy,"proxy.jpg",new MemoryStream(variants.Proxy,false),ct);var a=new StoredAsset(asset,name,sha,proxy.Bytes,thumb.ObjectKey,preview.ObjectKey,proxy.ObjectKey);p.Assets.Add(asset,a);p.Status="Ready";p.Revision++;return Uploaded(p,a);},true,ct);
 public Task<PublishedLinkResponse> Publish(Guid id,string token,PublishWithRuleRequest req,string baseUrl,CancellationToken ct)=>State(db=>{var p=Auth(db,id,token);var r=req.Rule;if(p.Assets.Count==0)throw Fail(409,"NoReadyAssets","Upload must be confirmed by the service.");if(r.TargetCount<1||r.MinimumCount<0||r.MaximumCount<r.TargetCount||r.MinimumCount>r.TargetCount||r.MaximumCount>p.Assets.Count||!r.LockAfterConfirmation||r.AllowComments||r.AllowDownload||r.AllowExtraSelections||r.RequirePin||r.ApplyWatermark||r.ExtraSelectionPriceMinor!=0)throw Fail(400,"UnsupportedRule","v1 requires valid counts, confirmation lock, no PIN/watermark/comments/download/extra/charges.");var expires=req.AccessExpiresAtUtc??DateTimeOffset.UtcNow.AddDays(7);if(expires<=DateTimeOffset.UtcNow||expires>DateTimeOffset.UtcNow.AddDays(90))throw Fail(400,"InvalidExpiry","Expiry must be in the next 90 days.");if(p.Locked)throw Fail(409,"SelectionLocked","Confirmed result is locked.");if(p.Rule.DeadlineUtc<=DateTimeOffset.UtcNow)throw Fail(409,"SelectionDeadlineExpired","Selection deadline has passed.");var client=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));p.ClientHash=Hash(client);p.Expires=expires;p.Rule=r;p.Target=r.TargetCount;p.Status="Published";p.Revision++;return Task.FromResult(new PublishedLinkResponse(id,p.PublicId,baseUrl.TrimEnd('/')+"/s/"+p.PublicId+"#token="+client,p.Version,p.Revision,expires));},true,ct);
 public Task<bool> Unpublish(Guid id,string token,CancellationToken ct)=>State(db=>{var p=Auth(db,id,token);p.ClientHash=null;p.Status="Ready";p.Revision++;return Task.FromResult(true);},true,ct);
 public Task<StoredProject> Client(string publicId,string token,CancellationToken ct)=>State(db=>{var found=db.Values.FirstOrDefault(p=>p.PublicId==publicId)??throw Fail(404,"ProjectNotFound","Album not found.");return Task.FromResult(Auth(db,found.Id,token,true));},ct:ct);
 public Task<int> PublicStatus(string publicId,CancellationToken ct)=>State(db=>{var p=db.Values.FirstOrDefault(p=>p.PublicId==publicId);return Task.FromResult(p is null||p.ClientHash is null||p.Status is not("Published"or"ClientConfirmed")?404:p.Expires<=DateTimeOffset.UtcNow?410:200);},ct:ct);
 public async Task<SelectionAssetPageResponse> Assets(string publicId,string token,CancellationToken ct){var p=await Client(publicId,token,ct);return new(p.Assets.Values.Select((a,i)=>new SelectionAssetResponse(a.Id,null,p.Rule.ShowFileNames?a.Name:$"照片 {i+1}",$"/v1/client/selection/{publicId}/assets/{a.Id}/thumb",$"/v1/client/selection/{publicId}/assets/{a.Id}/preview","Ready",i){Selected=a.Selected,Favorite=a.Favorite}).ToArray(),null,100);}
 public Task<SelectionMutationResponse> Choose(string publicId,Guid asset,string token,SelectionChoiceRequest req,CancellationToken ct)=>State(db=>{var byPublic=db.Values.FirstOrDefault(p=>p.PublicId==publicId)??throw Fail(404,"ProjectNotFound","Album not found.");var p=Auth(db,byPublic.Id,token,true);if(p.Locked)throw Fail(409,"SelectionLocked","Confirmed result is locked.");if(p.Rule.DeadlineUtc<=DateTimeOffset.UtcNow)throw Fail(409,"SelectionDeadlineExpired","Selection deadline has passed.");if(string.IsNullOrWhiteSpace(req.OperationId)||req.OperationId.Length>128)throw Fail(400,"InvalidOperationId","Operation identity required.");if(p.Operations.Contains(req.OperationId)){if(!p.Assets.TryGetValue(asset,out var seen)||seen.Selected!=req.Selected||seen.Favorite!=req.Favorite)throw Fail(409,"IdempotencyConflict","Selection retry changed.");return Task.FromResult(Mutation(p,asset));}if(req.ExpectedSelectionVersion!=p.Version||req.ExpectedRevision!=p.Revision)throw Fail(409,"SelectionConflict","Refresh current selection before editing.");if(!p.Assets.TryGetValue(asset,out var a))throw Fail(404,"AssetNotFound","Asset is not in this album.");var selected=p.Assets.Values.Count(x=>x.Selected)-(a.Selected?1:0)+(req.Selected?1:0);if(selected>p.Rule.MaximumCount)throw Fail(400,"SelectionCountInvalid","Selection limit reached.");if(req.Favorite&&!p.Rule.AllowFavorites)throw Fail(400,"FavoritesDisabled","Favorites are disabled.");p.Assets[asset]=a with{Selected=req.Selected,Favorite=req.Favorite};p.Operations.Add(req.OperationId);p.Status="Published";p.Revision++;return Task.FromResult(Mutation(p,asset));},true,ct);
 public Task<FinalSelectionSnapshotResponse> Confirm(string publicId,string token,ConfirmSelectionRequest req,CancellationToken ct)=>State(db=>{var byPublic=db.Values.FirstOrDefault(p=>p.PublicId==publicId)??throw Fail(404,"ProjectNotFound","Album not found.");var p=Auth(db,byPublic.Id,token,true);if(p.Locked)return Task.FromResult(Snapshot(p,true));if(p.Rule.DeadlineUtc<=DateTimeOffset.UtcNow)throw Fail(409,"SelectionDeadlineExpired","Selection deadline has passed.");if(!req.Confirmed||string.IsNullOrWhiteSpace(req.ConfirmationNonce)||req.ExpectedSelectionVersion!=p.Version||req.ExpectedRevision!=p.Revision)throw Fail(409,"SelectionConflict","Confirm the current selection revision.");var n=p.Assets.Values.Count(a=>a.Selected);if(n<p.Rule.MinimumCount||n>p.Rule.MaximumCount)throw Fail(400,"SelectionCountInvalid","Selection is outside allowed count.");p.Locked=true;p.Status="ClientConfirmed";p.ConfirmedAt=DateTimeOffset.UtcNow;p.Revision++;p.ConfirmedRevision=p.Revision;return Task.FromResult(Snapshot(p,true));},true,ct);
 public Task<FinalSelectionSnapshotResponse> Final(Guid id,string token,CancellationToken ct)=>State(db=>{var p=Auth(db,id,token);if(!p.Locked)throw Fail(409,"FinalSelectionUnavailable","Customer has not confirmed.");return Task.FromResult(Snapshot(p));},ct:ct);
 public Task<SelectionProgressResponse> Progress(Guid id,string token,CancellationToken ct)=>State(db=>Task.FromResult(ProgressOf(Auth(db,id,token))),ct:ct);
 public Task<bool> Delete(Guid id,Guid asset,string token,CancellationToken ct)=>State(db=>{var p=Auth(db,id,token);if(p.Locked||p.Status=="Published")throw Fail(409,"SelectionLocked","Unpublish before deleting a cloud copy.");p.Assets.Remove(asset);p.Revision++;return Task.FromResult(true);},true,ct);
 public async Task<string> Media(string pub,Guid asset,string token,string variant,CancellationToken ct){var p=await Client(pub,token,ct);if(!p.Assets.TryGetValue(asset,out var a))throw Fail(404,"AssetNotFound","Asset is not in this album.");return variant switch{"thumb"=>a.Thumb,"preview"=>a.Preview,_=>throw Fail(404,"VariantNotFound","Variant unavailable.")};}
 public static SelectionProjectResponse Project(StoredProject p)=>new(p.Id,p.PublicId,p.Name,p.Status,p.Target,p.Deadline){ClientDisplayName=p.Client,SelectionVersion=p.Version,Revision=p.Revision};
 static LocalDevAssetUploadResponse Uploaded(StoredProject p,StoredAsset a)=>new(p.Id,a.Id,null,a.Name,"Ready",a.Bytes,0,0,p.Version,p.Revision){UploadSha256=a.UploadSha};
 static SelectionMutationResponse Mutation(StoredProject p,Guid? asset)=>new(p.Id,asset,p.Version,p.Revision,p.Locked,DateTimeOffset.UtcNow);
 static FinalSelectionSnapshotResponse Snapshot(StoredProject p,bool clientView=false)=>new(p.Id,p.Version,p.ConfirmedRevision??p.Revision,p.Assets.Values.Select((a,index)=>new FinalSelectionItemResponse(p.Id,a.Id,clientView&&!p.Rule.ShowFileNames?$"照片 {index+1}":a.Name,a.Selected,a.Favorite,null,false)).ToArray(),p.ConfirmedAt??throw Fail(409,"FinalSelectionUnavailable","Not confirmed."),p.Locked);
 public static SelectionProgressResponse ProgressOf(StoredProject p)=>new(p.Id,p.Assets.Count,p.Assets.Count,p.Assets.Values.Count(a=>a.Selected),p.Assets.Values.Count(a=>a.Favorite),0,p.ConfirmedAt);
 public static SelectionRuleResponse RuleOf(StoredProject p)=>new(p.Rule.TargetCount,p.Rule.MinimumCount,p.Rule.MaximumCount,p.Rule.AllowExtraSelections,p.Rule.AllowComments,p.Rule.AllowFavorites,p.Rule.AllowDownload,p.Rule.ShowFileNames,p.Rule.ApplyWatermark,p.Rule.DeadlineUtc,p.Rule.RequirePin,p.Rule.LockAfterConfirmation);
 public void Dispose(){processLock.Dispose();gate.Dispose();}
}
